import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/services.dart';

import '../storage/settings_service.dart';

/// Sound effects, ambient music and haptics.
///
/// The effects are original, synthesised tones generated by
/// `tools/gen_sounds.py` — no third-party audio ships with the game. Playback
/// goes through a small pool of players so quick taps overlap instead of
/// cutting each other off.
///
/// Everything is defensive: if the audio engine is unavailable (no device
/// audio, widget tests, headless runs) the game plays exactly the same, just
/// silently. [initialize] is only called from `main()`, so tests never touch
/// the platform audio channels at all.
class AudioService {
  AudioService._();

  static final AudioService instance = AudioService._();

  static const String tapSound = 'sounds/tap.wav';
  static const String escapeSound = 'sounds/escape.wav';
  static const String blockedSound = 'sounds/blocked.wav';
  static const String winSound = 'sounds/win.wav';
  static const String musicSound = 'sounds/music.wav';

  static const double _sfxVolume = 0.85;
  static const double _musicVolume = 0.30;

  final List<AudioPlayer> _pool = <AudioPlayer>[];
  AudioPlayer? _music;
  int _next = 0;
  bool _enabled = false;
  bool _musicOn = false;

  SettingsService get _settings => SettingsService.instance;

  /// True once the audio engine is up.
  bool get enabled => _enabled;

  /// Starts the audio engine. Safe to call more than once.
  Future<void> initialize() async {
    if (_enabled) return;
    try {
      for (var i = 0; i < 4; i++) {
        final AudioPlayer player = AudioPlayer();
        try {
          await player.setPlayerMode(PlayerMode.lowLatency);
        } catch (_) {
          // Low latency is a nice-to-have; the default mode still works.
        }
        await player.setReleaseMode(ReleaseMode.stop);
        _pool.add(player);
      }
      final AudioPlayer music = AudioPlayer();
      await music.setReleaseMode(ReleaseMode.loop);
      _music = music;
      _enabled = true;
    } catch (_) {
      _enabled = false;
      return;
    }
    _settings.addListener(_onSettingsChanged);
    await _syncMusic();
  }

  /// Frees the players (used when the app is torn down).
  Future<void> dispose() async {
    _settings.removeListener(_onSettingsChanged);
    for (final AudioPlayer player in _pool) {
      try {
        await player.dispose();
      } catch (_) {}
    }
    _pool.clear();
    try {
      await _music?.dispose();
    } catch (_) {}
    _music = null;
    _enabled = false;
  }

  // ---- Effects -----------------------------------------------------------

  /// Button press.
  void tap() {
    _effect(tapSound);
    _haptic(HapticFeedback.selectionClick);
  }

  /// A successful escape.
  void escape() {
    _effect(escapeSound);
    _haptic(HapticFeedback.lightImpact);
  }

  /// A refused move.
  void blocked() {
    _effect(blockedSound);
    _haptic(HapticFeedback.mediumImpact);
  }

  /// Level completed.
  void win() {
    _effect(winSound);
    _haptic(HapticFeedback.heavyImpact);
  }

  /// A reward was earned (hint from a rewarded ad).
  void reward() {
    _effect(winSound);
    _haptic(HapticFeedback.mediumImpact);
  }

  // ---- Internals ---------------------------------------------------------

  void _effect(String asset) {
    if (!_enabled || !_settings.soundOn || _pool.isEmpty) return;
    final AudioPlayer player = _pool[_next % _pool.length];
    _next++;
    // Fire and forget: a failed effect must never break gameplay.
    () async {
      try {
        await player.stop();
        await player.play(AssetSource(asset), volume: _sfxVolume);
      } catch (_) {}
    }();
  }

  void _haptic(Future<void> Function() effect) {
    if (!_settings.vibrationOn) return;
    try {
      effect();
    } catch (_) {
      // Haptics are a nicety; never let them break gameplay.
    }
  }

  void _onSettingsChanged() {
    _syncMusic();
  }

  Future<void> _syncMusic() async {
    final bool want = _enabled && _settings.musicOn;
    if (want == _musicOn) return;
    _musicOn = want;
    final AudioPlayer? music = _music;
    if (music == null) return;
    try {
      if (want) {
        await music.setVolume(_musicVolume);
        await music.play(AssetSource(musicSound));
      } else {
        await music.stop();
      }
    } catch (_) {
      // Music is a nicety; never let it break gameplay.
    }
  }
}
